667: fn append_labeled_rows_from_extracted(
668:     eb: &ExtractedBatch,
669:     shard_id: i64,
670:     truth: &TruthResolver,
671:     pop_id_to_token: &[i64],
672:     rows: &mut Vec<Row>,
673:     seen_intervals: &mut HashSet<(i64, u64, u64)>,
674:     max_subgraphs: usize,
675: ) -> bool {
676:     let n = eb.node_ids.len();
677:     let seq_len = eb.seq_len;
678:     for r in 0..n {
679:         let node_id = eb.node_ids[r];
680:         let interval = eb.intervals[r];
681:         let key = interval_key(shard_id, interval.0, interval.1);
682:         let is_new = !seen_intervals.contains(&key);
683:         if max_subgraphs > 0 && is_new && seen_intervals.len() >= max_subgraphs {
684:             return true;
685:         }
686:         let Some(label) = truth.label_for(node_id, interval.0, interval.1) else {
687:             continue;
688:         };
689:         if label < 0 {
690:             continue;
691:         }
692:         let p0 = r * seq_len;
693:         let m0 = r * seq_len * seq_len;
694:         if is_new {
695:             seen_intervals.insert(key);
696:         }
697:         rows.push(Row {
698:             shard_id,
699:             node_id,
700:             tree_start: interval.0,
701:             tree_end: interval.1,
702:             input_ids: eb.pop_ids_flat[p0..p0 + seq_len]
703:                 .iter()
704:                 .map(|&pid| token_for_pop_id(pid, pop_id_to_token))
705:                 .collect(),
706:             tmrca: eb.matrices_flat[m0..m0 + seq_len * seq_len]
707:                 .iter()
708:                 .map(|&x| x as i16)
709:                 .collect(),
710:             label,
711:         });

724: fn build_chunks(
725:     rows: &mut [Row],
726:     recomb: &RecombMap,
727:     chunk_rows: usize,
728:     chunk_stride: usize,
729: ) -> Result<Chunks> {
730:     let seq_len = rows[0].input_ids.len();
731:     rows.sort_by(|a, b| {
732:         (a.shard_id, a.node_id, (a.tree_start * 1e6) as i64).cmp(&(
733:             b.shard_id,
734:             b.node_id,
735:             (b.tree_start * 1e6) as i64,
736:         ))
737:     });
738:     let mut groups: HashMap<(i64, i32), Vec<usize>> = HashMap::new();
739:     for (idx, row) in rows.iter().enumerate() {
740:         groups
741:             .entry((row.shard_id, row.node_id))
742:             .or_default()
743:             .push(idx);
744:     }
745:     let mut specs = Vec::new();
746:     for idxs in groups.values() {
747:         let mut start = 0;
748:         while start < idxs.len() {
749:             let end = (start + chunk_rows).min(idxs.len());
750:             specs.push(idxs[start..end].to_vec());
751:             if start + chunk_rows >= idxs.len() {
752:                 break;
753:             }
754:             start += chunk_stride;
755:         }
756:     }
757:     let n_chunks = specs.len();
758:     let mut ids = vec![0i64; n_chunks * chunk_rows * seq_len];
759:     let mut tmrca = vec![0i16; n_chunks * chunk_rows * seq_len * seq_len];
760:     let mut labels = vec![-100i64; n_chunks * chunk_rows];
761:     let mut mask = vec![0u8; n_chunks * chunk_rows];
762:     let mut cm = vec![0f32; n_chunks * chunk_rows * 2];
763:     for (c, idxs) in specs.iter().enumerate() {
764:         let mut prev_start_cm: Option<f64> = None;
765:         for (pos, &ri) in idxs.iter().enumerate() {
766:             let row = &rows[ri];
767:             let id0 = (c * chunk_rows + pos) * seq_len;
768:             ids[id0..id0 + seq_len].copy_from_slice(&row.input_ids);
769:             let m0 = (c * chunk_rows + pos) * seq_len * seq_len;
770:             tmrca[m0..m0 + seq_len * seq_len].copy_from_slice(&row.tmrca);
771:             labels[c * chunk_rows + pos] = row.label;
772:             mask[c * chunk_rows + pos] = 1;
773:             let start_cm = recomb.at_bp(row.tree_start);
774:             let end_cm = recomb.at_bp(row.tree_end);
775:             let cm0 = (c * chunk_rows + pos) * 2;
776:             cm[cm0] = (end_cm - start_cm).max(0.0) as f32;
777:             cm[cm0 + 1] = prev_start_cm.map(|p| start_cm - p).unwrap_or(0.0) as f32;

900: fn read_references(path: &Path) -> Result<HashMap<i32, NodeMeta>> {
901:     let mut out = HashMap::new();
902:     for line in std::fs::read_to_string(path)?.lines() {
903:         let f: Vec<&str> = line.split_whitespace().collect();
904:         if f.len() >= 3 {
905:             out.insert(
906:                 f[0].parse()?,
907:                 NodeMeta {
908:                     pop: f[1].to_string(),
909:                     time: f[2].parse::<f64>()? as i32,
910:                 },
911:             );
912:         }
913:     }
914:     Ok(out)
915: }

104:     fn rebuild_sample_ref(
105:         &mut self,
106:         lifter: &LocalBinaryLift,
107:         _node_time: &[i32],
108:         preds: &[NodeId],
109:         refs: &[NodeId],
110:         pred_times: &[i32],
111:     ) -> u64 {
112:         let r_len = self.r_len;
113:         let sample_local_lookup_failures = AtomicU64::new(0);
114:         self.sample_ref_raw
115:             .par_chunks_mut(r_len)
116:             .zip(self.sample_ref_dist.par_chunks_mut(r_len))
117:             .enumerate()
118:             .for_each(|(p, (raw_row, dist_row))| {
119:                 let sample_local = lifter.local_of_node(preds[p]);
120:                 if sample_local.is_none() {
121:                     sample_local_lookup_failures.fetch_add(1, Ordering::Relaxed);
122:                 }
123:                 for r in 0..r_len {
124:                     let raw = encode_tmrca(match sample_local {
125:                         Some(sample_local) => lifter.tmrca_from_local_sample(sample_local, refs[r]),
126:                         None => None,
127:                     });
128:                     raw_row[r] = raw;
129:                     dist_row[r] = relative_distance_uncapped(pred_times[p], raw);
130:                 }
131:             });
132:         sample_local_lookup_failures.load(Ordering::Relaxed)
133:     }
