15: /// Select `num_refs` reference column indices from `distances[r]` (smaller = closer).
16: pub fn select_ref_indices_from_distances(
17:     distances: &[u32],
18:     num_refs: usize,
19:     drop_top_m_nearest: usize,
20: ) -> Vec<usize> {
21:     if num_refs == 0 || distances.is_empty() {
22:         return Vec::new();
23:     }
24: 
25:     let heap_k = num_refs
26:         .saturating_add(drop_top_m_nearest)
27:         .min(distances.len())
28:         .max(1);
29: 
30:     let mut scratch: Vec<(u32, usize)> = Vec::with_capacity(heap_k);
31:     for (r, &dist) in distances.iter().enumerate() {
32:         let candidate = (dist, r);
33:         if scratch.len() < heap_k {
34:             scratch.push(candidate);
35:             if scratch.len() == heap_k {
36:                 sort_worst_first(&mut scratch);
37:             }
38:         } else if better_pair(candidate, scratch[0]) {
39:             scratch[0] = candidate;
40:             sort_worst_first(&mut scratch);
41:         }
42:     }
43: 
44:     scratch.sort_unstable_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
45:     let mut effective_drop = drop_top_m_nearest.min(scratch.len().saturating_sub(1));
46:     while scratch.len().saturating_sub(effective_drop) < num_refs && effective_drop > 0 {
47:         effective_drop -= 1;
48:     }
49: 
50:     let mut out: Vec<usize> = scratch
51:         .iter()
52:         .skip(effective_drop)
53:         .take(num_refs)
54:         .map(|&(_, r)| r)
55:         .collect();

